#include <scoped_allocator>
#include <vector>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    using A = std::scoped_allocator_adaptor<std::allocator<int>>;
    A allocator, other;
    assert(allocator == other);
    auto outer = allocator.outer_allocator();
    (void)outer;
    auto &inner = allocator.inner_allocator();
    (void)inner;
    int *storage = allocator.allocate(1);
    allocator.construct(storage, 7);
    assert(*storage == 7 && allocator.max_size() >= 1);
    allocator.destroy(storage);
    allocator.deallocate(storage, 1);
    other = allocator;
    auto copy = allocator.select_on_container_copy_construction();
    assert(copy == allocator);
}
